  ]
}

{
  "status": "answered",
  "answer": "The speed limit in a built-up area is 50 km/h.",
  "general_tip": "In built-up areas, the default speed limit is 50 km/h unless another provision applies.",
  "evidence": [
    "The default speed limit applying to a driver for a length of road in a built-up area is 50km/h. (Doc 1, Part 3, Speed limits, 2)",
    "The default speed limit applying to a driver for any other length of road is 100km/h. (Doc 1, Part 3, Speed limits, 3)"
  ],
  "sources": [
    "[doc1_s24_c2]",
    "[doc1_s24_c6]"
  ]
}

{
  "status": "answered",
  "answer": "No, you should not cross the intersection when the lights are red. Wait until the lights change to green before crossing.",
  "general_tip": "Always follow the traffic lights. If the pedestrian lights are red, do not start crossing until they change to green. If the traffic lights are red or yellow, do not start crossing until they change to green.",
  "evidence": [
    "If the pedestrian lights show a red pedestrian light and the pedestrian has not already started crossing the intersection or road, the pedestrian must not start to cross until the pedestrian lights change to green. (Doc 2, 231)",
    "If the traffic lights show a red or yellow traffic light and the pedestrian has not already started crossing the intersection or road, the pedestrian must not start to cross until the traffic lights change to green or flashing yellow, or there is no red traffic light showing. (Doc 2, 232)"
  ],
  "sources": [
    "[doc2_s06_c1]",
    "[doc2_s06_c3]"
  ]
}
